1) File-level @supports template (REQ-TEST-FIX-TEMPLATE, REQ-TEST-FIX-PLACEHOLDER, REQ-TEST-FIX-SAFE, REQ-TEST-FIX-PRESERVE, REQ-TEST-FIX-NO-INFERENCE):

- Template builder with clear placeholders:

 function buildSupportsTemplateComment(customTemplate?: string): string {
 const baseTemplate =
 (customTemplate && customTemplate.trim()) ||
 '@supports docs/stories/XXX.X-STORY-NAME.story.md REQ-XXX-YYY REQ-XXX-ZZZ';

 const lines = [
 '/**',
 ` * ${baseTemplate}`,
 ' * TODO: Replace the placeholder story path and REQ-IDs with real values for this test file.',
 ' */',
 '',
 ];

 return lines.join('\n');
 }

- Safe insertion at top of file, preserving shebangs and only adding comments:

 function insertSupportsTemplate(fixer: any, sourceCode: any, customTemplate?: string) {
 const text: string = sourceCode.text || '';
 let insertIndex = 0;

 if (text.startsWith('#!')) {
 const firstNewline = text.indexOf('\n');
 insertIndex = firstNewline === NOT_FOUND ? text.length : firstNewline + 1;
 }

 const templateComment = buildSupportsTemplateComment(customTemplate);
 return fixer.insertTextBeforeRange([insertIndex, insertIndex], templateComment);
 }

- Main entry for enforcing file-level supports:

 export function ensureFileSupportsAnnotation(context: any, sourceCode: any, autoFixOptions: TestTraceabilityAutoFixOptions): void {
 const fileComments = sourceCode.getAllComments() || [];

 const fileHasSupports = fileComments.some((comment: any) => /@supports\b/.test(comment.value || ''));

 if (!fileHasSupports) {
 const node = (fileComments[0] as any) || (sourceCode.ast && (sourceCode.ast as any));

 context.report({
 node,
 messageId: 'missingFileSupports',
 fix: autoFixOptions.autoFixTestTemplate === false
 ? undefined
 : (fixer: any) => insertSupportsTemplate(fixer, sourceCode, autoFixOptions.testSupportsTemplate),
 });
 }
 }

This logic:
- Only adds comments, not code.
- Honors `autoFixTestTemplate` (no fix when false).
- Uses a placeholder template with explicit TODO guidance.
- Never attempts to infer real story paths or IDs, satisfying REQ-TEST-FIX-NO-INFERENCE.

2) Prefix normalization (REQ-TEST-FIX-PREFIX-FORMAT, REQ-TEST-FIX-SAFE, REQ-TEST-FIX-PRESERVE, REQ-TEST-FIX-NO-INFERENCE):

- Requirement ID normalization without inventing new IDs:

 function normalizeReqId(raw: string): string {
 let id = raw.trim().toUpperCase();

 if (!id.startsWith('REQ')) {
 return id;
 }

 let rest = id.slice(REQ_PREFIX_LENGTH);
 rest = rest.replace(/^[-_\s:]+/, '');
 rest = rest.replace(/[\s_]+/g, '-');
 rest = rest.replace(/-+/g, '-');
 return rest ? `REQ-${rest}` : 'REQ-';
 }

- Normalizing malformed prefixes only when a REQ identifier is already present:

 function normalizeReqPrefixInDescription(description: string): string | null {
 const canonicalPattern = /^\[REQ-[^\]]+]/;
 if (canonicalPattern.test(description)) {
 return null;
 }

 const squareMatch = description.match(/^\[\s*(REQ[^\]]*?)\s*](.*)$/i);
 if (squareMatch) {
 const normalizedId = normalizeReqId(squareMatch[1]);
 return `[${normalizedId}]${squareMatch[2] ?? ''}`;
 }

 const parenMatch = description.match(/^\(\s*(REQ[^)]*?)\s*\)(.*)$/i);
 if (parenMatch) {
 const normalizedId = normalizeReqId(parenMatch[1]);
 return `[${normalizedId}]${parenMatch[2] ?? ''}`;
 }

 return null;
 }

- Applying fixes only when safe and preserving literal formatting:

 function handleItOrTestCall(context: any, node: any, description: string, options: CallExpressionOptions): void {
 const { sourceCode, requireTestReqPrefix, autoFixTestPrefixFormat } = options;
 if (!requireTestReqPrefix) return;

 if (!/^\[REQ-[^\]]+]/.test(description)) {
 const normalizedDescription =
 autoFixTestPrefixFormat !== false
 ? normalizeReqPrefixInDescription(description)
 : null;

 context.report({
 node,
 messageId: 'missingReqPrefix',
 ...(autoFixTestPrefixFormat !== false &&
 normalizedDescription !== null &&
 node.arguments &&
 node.arguments[0] &&
 node.arguments[0].type === 'Literal' &&
 typeof node.arguments[0].value === 'string'
 ? {
 fix(fixer: any) {
 const literalNode = node.arguments[0];
 const newRaw = createUpdatedStringLiteralRaw(literalNode, normalizedDescription, sourceCode);
 return fixer.replaceText(literalNode, newRaw);
 },
 }
 : {}),
 });
 }
 }

- createUpdatedStringLiteralRaw preserves original quote style and escaping, ensuring formatting is preserved and only the string value changes:

 function createUpdatedStringLiteralRaw(originalNode: any, newValue: string, sourceCode: any): string {
 const raw = sourceCode.getText(originalNode);
 const firstChar = raw[0];

 if (QUOTES.includes(firstChar as any)) {
 const quote = firstChar;
 const escaped = newValue
 .replace(/\\/g, '\\\\')
 .replace(new RegExp(`\\${quote}`, 'g'), `\\${quote}`);
 return `${quote}${escaped}${quote}`;
 }

 return JSON.stringify(newValue);
 }

This implementation:
- Only modifies test name string literals when a recognizable REQ ID is present and when `autoFixTestPrefixFormat` is not false.
- Does not introduce new IDs or attempt to guess them.
- Preserves quote style and escaping, satisfying REQ-TEST-FIX-PRESERVE and REQ-TEST-FIX-SAFE."}, {"type":"documentation","description":"User-facing documentation describing Story 021.0 auto-fix capabilities and templates","details":"user-docs/api-reference.md, section `traceability/require-test-traceability` (lines 220–280):

